from pathlib import Path
root=Path(__file__).resolve().parent.parent
s=(root/'sprint-helper.js').read_text()
helpers=s[s.index('function parsePoints('):s.index('// Helper: Check if card title')]+s[s.index('function s4tIsCommonCard('):s.index('function s4tIsCommonCardElement(')]
setup='''function getBoardShortLink(){return 'fixture'};const board={name:'Sprint',members:[{id:'a',fullName:'Alex'},{id:'b',fullName:'Blair'},{id:'c',fullName:'Chris'}],lists:[],cards:[{id:'1',name:'(4) Work',idMembers:['a'],labels:[{id:'h',name:'Hotfix'}]},{id:'2',name:'(2) Other',idMembers:['b'],labels:[]}]};function fetchBoardData(id,force,cb){setTimeout(()=>cb(null,board),5)};let popup;window.open=()=>{popup={document:document.implementation.createHTMLDocument('Charts'),close(){this.closed=true}};return popup};'''
tests='''(async()=>{const wait=ms=>new Promise(r=>setTimeout(r,ms)),errors=[],check=(v,m)=>{if(!v)errors.push(m)},el=s=>document.querySelector(s);try{s4tOpenCharts();await wait(50);check(document.querySelectorAll('.s4t-chart-slice').length===2,'two developer slices');const slice=el('.s4t-chart-slice');slice.dispatchEvent(new MouseEvent('mouseenter'));check(slice.style.transform.includes('translate'),'hover peeks out');slice.click?.();slice.dispatchEvent(new MouseEvent('click'));check(slice.getAttribute('aria-pressed')==='true','slice selection pinned');el('[data-chart-tab="labels"]').click();check(el('.s4t-chart-note').textContent.includes('Multi-label'),'overlap explained');check(el('.s4t-chart-legend').textContent.includes('Hotfix'),'label names shown');el('[data-chart-popout]').click();check(popup.document.querySelector('[data-chart-tab="labels"]').getAttribute('aria-selected')==='true','popout retains selected tab');check(popup.document.querySelectorAll('.s4t-chart-slice').length===2,'popout rendered chart');el('[data-chart-close]').click();check(!el('.s4t-chart-overlay'),'popup closes');}catch(e){errors.push(e.stack)}el('#result').textContent=errors.length?'FAIL: '+errors.join('; '):'PASS: pie slices, hover, selection, tabs, popout and close';})();'''
Path('/tmp/s4t-charts-ui.html').write_text('<html><body><pre id="result">RUNNING</pre><script>'+setup+helpers+(root/'charts.js').read_text()+tests+'</script></body></html>')
